"use client"

import { motion, useInView } from "framer-motion"
import { useRef, useEffect, useState } from "react"
import { SectionHeader } from "./section-header"

function AnalysisViewport() {
  const ref = useRef<HTMLDivElement>(null)
  const isInView = useInView(ref, { once: true })

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 16 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
      className="mx-auto max-w-4xl"
    >
      {/* Before / After labels */}
      <div className="mb-3 flex items-center">
        <span className="flex-1 font-mono text-[10px] tracking-[0.2em] text-muted-foreground uppercase">
          Before
        </span>
        <span className="flex-1 text-right font-mono text-[10px] tracking-[0.2em] text-muted-foreground uppercase">
          After
        </span>
      </div>

      {/* Split viewport */}
      <div className="relative flex aspect-video overflow-hidden border border-border">
        {/* Left: Before */}
        <div className="relative flex-1 bg-card">
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="font-mono text-[11px] text-muted-foreground/30 tracking-widest uppercase">
              RGB Frame
            </span>
          </div>
        </div>

        {/* Center divider */}
        <div className="relative z-10 w-px bg-foreground/15" />

        {/* Right: After */}
        <div className="relative flex-1 bg-card">
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="font-mono text-[11px] text-muted-foreground/30 tracking-widest uppercase">
              Thermal Frame
            </span>
          </div>

          {/* Subtle detection markers */}
          {isInView && (
            <>
              <motion.div
                className="absolute border border-foreground/15"
                style={{ left: "55%", top: "25%", width: 36, height: 36 }}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.2, duration: 0.8 }}
              />
              <motion.div
                className="absolute border border-foreground/15"
                style={{ left: "20%", top: "55%", width: 28, height: 28 }}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.6, duration: 0.8 }}
              />
            </>
          )}
        </div>

        {/* Corner metadata */}
        <div className="absolute bottom-3 left-3">
          <span className="font-mono text-[10px] text-muted-foreground/30">1920 x 1080</span>
        </div>
        <div className="absolute bottom-3 right-3">
          <span className="font-mono text-[10px] text-muted-foreground/30">2 regions</span>
        </div>
      </div>
    </motion.div>
  )
}

function DifferenceScore() {
  const ref = useRef<HTMLDivElement>(null)
  const isInView = useInView(ref, { once: true })
  const [score, setScore] = useState(0)

  useEffect(() => {
    if (!isInView) return
    const target = 87.4
    const duration = 2000
    const startTime = performance.now()
    function tick(now: number) {
      const elapsed = now - startTime
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      setScore(+(target * eased).toFixed(1))
      if (progress < 1) requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }, [isInView])

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5, delay: 0.3 }}
      className="mx-auto mt-16 flex max-w-md flex-col items-center gap-6"
    >
      <span className="font-mono text-[11px] tracking-[0.25em] text-muted-foreground uppercase">
        Difference Score
      </span>

      <div className="flex items-end gap-2">
        <span className="font-mono text-5xl font-extralight text-foreground tabular-nums">
          {score}
        </span>
        <span className="mb-1.5 font-mono text-sm text-muted-foreground/50">/ 100</span>
      </div>

      {/* Progress bar */}
      <div className="w-full">
        <div className="h-px w-full bg-border">
          <motion.div
            className="h-px bg-foreground/60"
            initial={{ width: "0%" }}
            animate={isInView ? { width: `${score}%` } : {}}
            transition={{ duration: 2, ease: "easeOut" }}
          />
        </div>
        <div className="mt-2 flex items-center justify-between">
          <span className="font-mono text-[9px] text-muted-foreground/40 tracking-wider uppercase">0</span>
          <span className="font-mono text-[9px] text-muted-foreground/40 tracking-wider uppercase">50</span>
          <span className="font-mono text-[9px] text-muted-foreground/40 tracking-wider uppercase">100</span>
        </div>
      </div>
    </motion.div>
  )
}

export function AnalysisSection() {
  return (
    <section className="relative px-6 py-32">
      <SectionHeader
        label="02"
        title="ANALYSIS"
        subtitle="Side-by-side comparison with automated region detection"
      />
      <AnalysisViewport />
      <DifferenceScore />
    </section>
  )
}
